css:
.liquid-mercury {
  width: 100%;
  height: 100%;
  background-color: #333;
  position: relative;
  overflow: hidden;
}

.liquid-mercury::before {
  content: "";
  position: absolute;
  top: -5%;
  left: -5%;
  width: 110%;
  height: 110%;

  filter: url(#mercury);
  /* animation: slow-roll 45s linear infinite; */
}

@keyframes slow-roll {
  from {
    transform: rotate(0deg) scale(1.1);
  }
  to {
    transform: rotate(360deg) scale(1.1);
  }
}
